connect-usability.css:
/* Keep inbox SVG-use strokes at the approved cream without deferred currentColor paint. */
#search-toggle .icon,#compose-toggle .icon{stroke:#f3e9d8}

/* UX-03 portrait correction: a single explicit circular clip avoids rounded-image/background double rasterization. */
.story-ring img{border-radius:0;clip-path:circle(50%);background:transparent}
.list-avatar{background:transparent}

/* UX-03 focused review refinement — compact, relational Connect surfaces. */
.people-rail{gap:12px;padding-block:2px 6px;margin-bottom:12px;justify-content:flex-start}
.people-rail .person{flex:0 0 62px;width:62px;gap:6px}
.story-ring{width:58px;height:58px;border-color:#57585c;padding:2px}
.person>span:last-child{font-size:.8125rem;line-height:1.25}
.inbox-headline{margin:10px 0 12px}
.inbox-headline p{font-size:.9375rem}
.section-top h3{font-size:1.125rem;letter-spacing:-.03em}
.conversation-list{gap:0;border-block:1px solid #3b3c40}
.conversation-row,.conversation-row:first-child{border:0;border-bottom:1px solid #3b3c40;border-radius:0;background:transparent;min-height:88px;padding:13px 0;gap:12px}
.conversation-row:last-child{border-bottom:0}
.conversation-row:has(.unread:not([hidden])){border-left:0}
.conversation-row .list-avatar{width:56px;height:56px;border:1px solid #57585c}
.conversation-copy strong{font-size:1.0625rem;line-height:1.3;font-weight:800}
.conversation-copy>span{font-size:.9375rem;line-height:1.45;color:#c8c6c1;white-space:normal;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.conversation-side time{font-size:.75rem;font-weight:550;color:#c8c6c1}
.conversation-side .unread{min-width:22px;height:22px;font-size:.6875rem}
.chat-header{min-height:60px;padding-block:6px}
.chat-header-title h2{font-size:1.125rem;line-height:1.2}
:is(#thread-scroll,#direct-scroll,#room-scroll) .message{gap:8px;margin-bottom:18px}
:is(#thread-scroll,#direct-scroll,#room-scroll) .message-stack{gap:3px;max-width:min(85%,372px)}
:is(#thread-scroll,#direct-scroll,#room-scroll) .bubble{font-size:1.125rem;line-height:1.48;padding:11px 14px;border-radius:18px 18px 18px 5px;font-weight:500}
:is(#thread-scroll,#direct-scroll,#room-scroll) .outgoing .bubble{border-radius:18px 18px 5px 18px}
:is(#thread-scroll,#direct-scroll,#room-scroll) .message-author{font-size:.8125rem;font-weight:800;padding:0 3px 2px}
:is(#thread-scroll,#direct-scroll,#room-scroll) .message time{font-size:.75rem;font-weight:500;color:#c0beb9;margin:3px 3px 0}
.message-avatar{width:32px;height:32px;margin-bottom:22px;border:1px solid #57585c}
.room-hero{min-height:0;gap:5px;padding:5px 14px 9px}
.room-hero-toolbar{min-height:44px}
.room-label{font-size:.625rem;letter-spacing:.13em}
.hero-flag{width:23px;height:23px}
.room-identity{align-items:center;gap:10px;padding-inline:4px}
.room-identity h2{font-size:1.375rem;line-height:1.15;margin:0 0 3px;letter-spacing:-.035em}
.room-identity h2 br{display:inline}.room-identity h2 br::after{content:' '}
.room-identity h2{white-space:normal}
.room-identity p{font-size:.75rem;line-height:1.35}
.room-mark{width:38px;height:38px;border:1px solid #57585c}.room-mark img{width:24px;height:24px}
.room-tabs{padding:6px 14px 9px;gap:6px}
.event-card{min-height:0;margin:8px 0 18px;padding:14px;background:#292a2d;color:#f3e9d8;border:1px solid #494a4e;border-radius:16px;display:grid;grid-template-columns:1fr auto;gap:5px 12px;align-items:center}
.event-card:before{display:none}
.event-eyebrow{grid-column:1/-1;font-size:.625rem;color:#ffb3bf;gap:7px;line-height:1.4}
.event-eyebrow .icon{width:16px;height:16px}
.event-card h3{font-size:1.375rem;margin:4px 0 0;line-height:1.15;letter-spacing:-.035em}
.event-card p{grid-column:1;margin:0;font-size:.8125rem;line-height:1.4;color:#d0cbc3}
.event-card .rsvp-action{grid-column:2;grid-row:2/4;width:auto;min-height:44px;padding:10px 12px;background:#f3e9d8;color:#252629;font-size:.8125rem;border-radius:999px;margin:0}
.event-disclaimer{position:static;grid-column:1/-1;font-size:.5625rem;color:#c8c6c1;margin-top:3px;letter-spacing:.1em}
#room-panel-people .panel-kicker{font-size:.625rem;color:#ffb3bf;margin-bottom:9px}
#room-panel-people .panel-title{font-size:1.75rem;line-height:1.05;letter-spacing:-.045em;margin:0 0 18px;max-width:260px;color:#f3e9d8}
#room-panel-people .member{background:transparent;border:0;border-bottom:1px solid #3b3c40;border-radius:0;padding:14px 0;margin:0;gap:14px}
#room-panel-people .member img{width:58px;height:58px;border:1px solid #57585c}
#room-panel-people .member strong{font-size:1.125rem;font-weight:750}
#room-panel-people .member span{font-size:.875rem;color:#c8c6c1;line-height:1.5;margin-top:3px}
#room-panel-people .panel-note{line-height:1.5;color:#c8c6c1}
@media(max-width:350px){.conversation-row .list-avatar{width:50px;height:50px}.conversation-row{gap:10px}.people-rail{gap:9px}.people-rail .person{flex-basis:58px;width:58px}.event-card{gap:5px 8px;padding:12px}.event-card .rsvp-action{font-size:.75rem;padding-inline:10px}}
@media(max-height:600px){.room-hero{min-height:0;padding-top:2px;gap:2px}.room-hero-toolbar{min-height:40px}.room-identity h2{font-size:1.25rem}}

/* UX-03: Connect-only premium presentation. State and fixtures remain source-owned. */
:root{--ca-graphite:#17181a;--ca-card:#292a2d;--ca-raised:#323337;--ca-line:#494a4e;--ca-cream:#f3e9d8;--ca-dim:#d0cbc3;--ca-red:#e3002b;--red:#e3002b}
.app-frame,.mock-status,.inbox-header,.screen-inbox,.screen-dark,.chat-scroll,.room-scroll{background:#17181a;color:#f3e9d8}
.inbox-header{padding-top:12px}
.inbox-headline{margin:12px 0}
.connect-alive-eyebrow{font-size:.625rem;margin:0 0 8px;color:#d0cbc3}
.inbox-headline h2{font-size:clamp(2.25rem,10vw,2.75rem);letter-spacing:-.065em;line-height:1}
.inbox-headline p{font-size:.875rem;margin-top:7px;color:#d0cbc3}
.full-stop{color:#ff536e}
.inbox-body{padding-top:8px}
.section-top{flex-wrap:wrap;gap:4px 10px}
.section-note{font-size:.625rem;color:#d0cbc3}
.people-rail{gap:10px;margin-bottom:16px;overflow-x:auto;padding:3px 2px 8px;justify-content:flex-start}
.person{flex:1 0 60px;min-width:60px}
.story-ring{width:54px;height:54px;padding:2px;border:1px solid #68696d;box-shadow:none;background:#292a2d}
.person>span:last-child{font-size:.75rem;white-space:normal}
.conversations-heading{margin:4px 0 10px}
.conversation-list{gap:8px}
.conversation-row,.conversation-row:first-child{min-height:80px;padding:12px;background:#292a2d;border:1px solid #494a4e;border-radius:16px;box-shadow:none}
.conversation-row:hover{background:#323337}
.conversation-row:has(.unread:not([hidden])){border-left:3px solid #ff536e}
.conversation-row .list-avatar{width:48px;height:48px;border:1px solid #68696d}
.conversation-copy strong{font-size:1rem;letter-spacing:-.025em;color:#f3e9d8}
.conversation-copy>span{font-size:.875rem;line-height:1.4;color:#d0cbc3}
.conversation-side time{font-size:.6875rem;color:#d0cbc3}
.conversation-side .unread{background:#e3002b;color:white;font-size:.75rem}
.moment-card{margin-top:18px;min-height:0;padding:16px;background:#292a2d;border:1px solid #494a4e;box-shadow:none}
.moment-card>strong{font-size:1.25rem;line-height:1.2}
.moment-card>span:nth-last-child(2){font-size:.875rem;color:#d0cbc3}
.moment-eyebrow{color:#ffb3bf}
.moment-action{background:#f3e9d8;color:#252629;margin-top:8px;font-size:.8125rem}
.chat-header{min-height:64px;padding-block:8px;background:#202124;border-color:#494a4e}
.chat-header-title h2{font-size:1.125rem;letter-spacing:-.025em}
.chat-header-title p{font-size:.75rem;color:#d0cbc3}
.chat-header-face{width:40px;height:40px;border:1px solid #68696d}
.chat-scroll,.room-scroll{padding:16px 14px}
:is(#thread-scroll,#direct-scroll,#room-scroll) .message{margin-bottom:16px}
:is(#thread-scroll,#direct-scroll,#room-scroll) .message-stack{max-width:min(85%,360px);gap:4px}
:is(#thread-scroll,#direct-scroll,#room-scroll) .bubble{font-size:1.0625rem;line-height:1.5;letter-spacing:-.015em;padding:11px 14px;border:0}
:is(#thread-scroll,#direct-scroll,#room-scroll) .incoming .bubble{background:#f3e9d8;color:#252629}
:is(#thread-scroll,#direct-scroll,#room-scroll) .outgoing .bubble{background:#e3002b;color:white}
:is(#thread-scroll,#direct-scroll,#room-scroll) .message-author{font-size:.8125rem;color:#f3e9d8}
:is(#thread-scroll,#direct-scroll,#room-scroll) .message time{font-size:.6875rem;color:#d0cbc3}
#thread-scroll .message-reply{font-size:.8125rem;background:#323337;color:#f3e9d8}
#thread-scroll .message-actions{gap:6px}
#thread-scroll .message-stack .reaction,#thread-scroll .message-reply-action{font-size:.75rem;background:#292a2d;border-color:#68696d}
.composer,#thread-form{background:#202124;border-color:#494a4e;padding:9px 12px max(9px,env(safe-area-inset-bottom))}
.composer textarea,#thread-form textarea{font-size:1rem;line-height:1.45;background:#323337;color:#f3e9d8;border-color:#68696d;border-radius:18px}
.composer .send-btn,#thread-form .send-btn{background:#e3002b;border:0;border-radius:50%}
.room-hero{min-height:150px;padding-bottom:12px;background:#202124}
.room-hero-image{background:none}
.room-identity h2{font-size:1.5rem;line-height:1.05}
.room-identity p{font-size:.75rem;color:#d0cbc3}
.room-mark{width:48px;height:48px;background:#292a2d;border:1px solid #494a4e}
.room-tabs{padding-block:8px;background:#17181a}
.room-tabs button{font-size:.875rem;min-height:44px;background:#292a2d;border-color:#494a4e}
.room-tabs button[aria-selected=true]{background:#f3e9d8;color:#252629;border-color:#f3e9d8}
.panel-title{font-size:1.875rem}
.member{background:#292a2d;border-color:#494a4e;border-radius:14px;padding:12px;margin-bottom:8px}
.member strong{font-size:1rem}.member span,.panel-note{font-size:.875rem}
.new-dialog{background:#f3e9d8}
.dialog-person{min-height:64px;font-size:1rem}
.no-results{padding:20px 8px;border:1px solid #494a4e;border-radius:14px;font-size:1rem}
:is(.conversation-row,.person,.composer .send-btn,.room-tabs button,.dialog-person):active{transform:scale(.98)}
@media(prefers-reduced-motion:no-preference){.conversation-row,.person,.composer .send-btn,.room-tabs button,.dialog-person{transition:transform .12s ease,background-color .15s ease}}
@media(prefers-reduced-motion:reduce){.conversation-row,.person,.composer .send-btn,.room-tabs button,.dialog-person{transition:none;transform:none}}
@media(max-width:350px){.conversation-row{gap:8px;padding:10px}.conversation-row .list-avatar{width:40px;height:40px}.conversation-side{min-width:0}.conversation-side time{white-space:normal;text-align:right;max-width:62px}}
@media(max-height:600px){.room-hero{min-height:112px}.room-identity h2{font-size:1.25rem}.inbox-headline{margin:8px 0}.connect-alive-eyebrow{margin-bottom:5px}}

rally-one-connect-alive-shell.css:
/* UX-03: compact return control; existing dialog, button name and focus owner retained. */
.rally-one .connect-overlay[open]{background:#17181a}
.rally-one .connect-overlay > button{align-self:flex-start;width:auto;max-width:calc(100% - 16px);height:44px;min-height:44px;margin:0 8px;padding:0 12px;border:0;border-radius:999px;background:transparent;color:#f3e9d8;font-size:12px;line-height:1.25;white-space:normal;text-align:left}
.rally-one .connect-overlay > button:hover{background:#292a2d}
.rally-one .connect-overlay iframe{background:#17181a}
